@startuml

class Ingredient {
  + name : string
  + measuringUnit : string
  + quantityInStock : float
}

class Dish {
  + name : string
  + id : int
}

class IngredientUsage {
  + quantity : float
}

class Table {
  + id : int
  + maxAmountOfPeople : int
}

class Meal {
  + date : date
  + startTime : time
  + endTime : time
}

class MealDish {
  + quantity : int
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Client {
  + taxIdentificationNumber : string
  + name : string
  + address : string
}

Dish "1" *-- "*" IngredientUsage
Ingredient "1" -- "*" IngredientUsage
Dish "1" -- "*" MealDish
Meal "1" *-- "*" MealDish
Meal "1" -- "1" Table
Meal "1" --> "0..1" Client
Meal "*" -- "1" Waiter

@enduml

